CREATE FUNCTION pg_temp.check03c(t text,payload jsonb,can_read boolean,can_write boolean,admin boolean) RETURNS void LANGUAGE plpgsql AS $$
DECLARE n int; inserted boolean:=false; newrow jsonb;
BEGIN
 EXECUTE format('SELECT count(*) FROM public.%I WHERE id=$1',t) INTO n USING (payload->>'id')::uuid;
 PERFORM pg_temp.assert03c(n=CASE WHEN can_read THEN 1 ELSE 0 END,'SELECT '||t);
 newrow:=payload || jsonb_build_object('id',gen_random_uuid(),'user_id',auth.uid());
 BEGIN EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I,$1)).*',t,t) USING newrow;
 inserted:=true; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM pg_temp.assert03c(inserted=can_write,'INSERT '||t);
 EXECUTE format('UPDATE public.%I SET organization_id=organization_id WHERE id=$1',t) USING (payload->>'id')::uuid;
 GET DIAGNOSTICS n=ROW_COUNT;
 PERFORM pg_temp.assert03c(n=CASE WHEN can_write THEN 1 ELSE 0 END,'UPDATE '||t);
 BEGIN EXECUTE format('DELETE FROM public.%I WHERE id=$1',t) USING (payload->>'id')::uuid;
 GET DIAGNOSTICS n=ROW_COUNT; RAISE SQLSTATE 'PT001'; EXCEPTION WHEN SQLSTATE 'PT001' THEN NULL; END;
 PERFORM pg_temp.assert03c(n=CASE WHEN admin THEN 1 ELSE 0 END,'DELETE admin only '||t);
END; $$;
CREATE FUNCTION pg_temp.cross03c(t text,col text,payload jsonb,foreign_id uuid) RETURNS void LANGUAGE plpgsql AS $$
DECLARE blocked boolean:=false; rowdata jsonb;
BEGIN
 rowdata:=payload || jsonb_build_object('id',gen_random_uuid(),col,foreign_id);
 BEGIN EXECUTE format('INSERT INTO public.%I SELECT (jsonb_populate_record(NULL::public.%I,$1)).*',t,t) USING rowdata;
 EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 PERFORM pg_temp.assert03c(blocked,'cross-tenant INSERT '||t||'.'||col);
 blocked:=false;
 BEGIN EXECUTE format('UPDATE public.%I SET %I=$1 WHERE id=$2',t,col) USING foreign_id,(payload->>'id')::uuid;
 EXCEPTION WHEN insufficient_privilege THEN blocked:=true; END;
 PERFORM pg_temp.assert03c(blocked,'cross-tenant UPDATE '||t||'.'||col);
END; $$;
