DO $$ DECLARE t text;blocked boolean; BEGIN FOREACH t IN ARRAY ARRAY['incomes','income_allocations','income_distributions','income_tax_reservations','expenses','client_funds','fund_movements','operational_reserve_movements','payroll_payments','company_settings','settings','exchange_rates','staff'] LOOP blocked:=false; BEGIN EXECUTE format('UPDATE public.%I SET organization_id=$1 WHERE id=$2',t) USING '95000000-0000-4000-8000-000000000101'::uuid,'95000000-0000-4000-8000-000000000200'::uuid; EXCEPTION WHEN check_violation OR insufficient_privilege THEN blocked:=true; END; PERFORM pg_temp.assert03c(blocked,'tenant move rejected '||t); END LOOP; END $$;
RESET ROLE;
SET LOCAL ROLE anon;
SELECT set_config('request.jwt.claim.sub','',true);
SELECT set_config('request.jwt.claims','{"role":"anon"}',true);
SELECT pg_temp.check03c(t,payload,false,false,false) FROM cases;
RESET ROLE;
SELECT pg_temp.assert03c(NOT has_function_privilege('anon','public.is_org_finance(uuid)','EXECUTE') AND has_function_privilege('authenticated','public.is_org_finance(uuid)','EXECUTE'),'finance EXECUTE minimal');
SELECT pg_temp.assert03c(NOT has_function_privilege('anon','public.get_org_branding(uuid)','EXECUTE'),'branding not public RPC');
SELECT pg_temp.assert03c((SELECT NOT prosecdef AND proconfig=ARRAY['search_path=""']::text[] FROM pg_proc WHERE oid='public.is_org_finance(uuid)'::regprocedure),'finance helper invoker and safe search_path');
SELECT pg_temp.assert03c((SELECT count(*)=46 FROM pg_tables WHERE schemaname='public'),'46 tables');
SELECT pg_temp.assert03c((SELECT count(*)=9 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f'),'nine public functions');
SELECT pg_temp.assert03c((SELECT count(*)=306 FROM pg_policies WHERE schemaname='public'),'306 policies');
SELECT pg_temp.assert03c((SELECT count(*)=126 FROM pg_policies WHERE schemaname='public' AND permissive='RESTRICTIVE'),'126 restrictive guards retained');
SELECT pg_temp.assert03c(NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='r' AND NOT c.relrowsecurity),'all RLS enabled');
ROLLBACK;
